class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        self.monthly_limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Structure: {month: {filename: size_bytes}}
        self._history: dict[str, dict[str, int]] = {}
        # Structure: {owner: set of filenames}
        self._owner_files: dict[str, set[str]] = {}

    def upload(
        self, name: str, size_bytes: int, month: str, owner: str = ""
    ) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0.")

        month_files = self._history.setdefault(month, {})

        # If file was already uploaded in this month, it does not count again.
        if name in month_files:
            return

        current_used = sum(month_files.values())
        if current_used + size_bytes > self.monthly_limit_bytes:
            raise ValueError(
                f"Upload of {size_bytes} bytes exceeds the monthly limit of "
                f"{self.monthly_limit_bytes} bytes for {month}."
            )

        month_files[name] = size_bytes
        self._owner_files.setdefault(owner, set()).add(name)

    def delete(self, name: str, month: str) -> None:
        """
        Deleting a file does not give back quota in the current month,
        so the recorded quota usage remains unchanged.
        """
        pass

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._history.get(month, {}).values())

    def remaining_bytes(self, month: str) -> int:
        """How many bytes can still be uploaded in the given month."""
        return self.monthly_limit_bytes - self.used_bytes(month)

    def files(self) -> list[str]:
        """Returns the names of all stored files, sorted."""
        stored_files: set[str] = set()
        for month_files in self._history.values():
            stored_files.update(month_files.keys())
        return sorted(stored_files)

    def files_of(self, owner: str) -> list[str]:
        """Returns the names of all files uploaded by the given owner, sorted."""
        return sorted(self._owner_files.get(owner, set()))
